#!/usr/bin/env node
// =============================================================================
// F1 / F1b: ninja-reverse-proxy vs nginx, real traffic, real processes.
// =============================================================================
// - Upstream, nginx, and the proxy are each spawned as their own OS process —
//   never imported into this script. Load is generated by the real `wrk` CLI,
//   also its own process.
// - For each target x payload: 10s warmup, then 30s @ 100 conns and 30s @ 500
//   conns. Records RPS, p50/p99/p99.9 latency, errors, and peak RSS across the
//   target's whole process tree (master + workers, where applicable).
// - F1b reruns the proxy alone with every production feature turned on
//   (rate limit high enough not to reject, cache on, tracing on, access log
//   on, Redis on) as a separate "ninja, all features on" row, to show the
//   real cost of those features.
// - Writes docs/results/bench-vs-nginx.md. Does not tune only one side.
// =============================================================================

import { spawn, execSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..");
const LUA_REPORT = path.join(__dirname, "bench", "wrk-report.lua");
const UPSTREAM_SCRIPT = path.join(__dirname, "bench", "upstream-server.mjs");

const UPSTREAM_PORT = 19001;
const REDIS_PORT = 19379;
const NGINX_PORT = 19100;
const NINJA_BASELINE_PORT = 19200;
const NINJA_FULL_PORT = 19201;
const WORKER_COUNT = 4;

// BENCH_WARMUP_SEC / BENCH_STAGE_SEC let this be smoke-tested quickly before committing to
// the full 10s warmup / 30s-per-stage run the task spec calls for (the default below).
const WARMUP_SEC = Number(process.env.BENCH_WARMUP_SEC) || 10;
const STAGE_SEC = Number(process.env.BENCH_STAGE_SEC) || 30;
const CONCURRENCIES = [100, 500];
const PAYLOADS = [
  { name: "1KB", path: "/small" },
  { name: "1MB", path: "/large" },
];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const children = [];
let upstreamProc, redisProc;

function log(msg) {
  console.log(`[bench-vs-nginx] ${msg}`);
}

function which(bin) {
  try {
    return execSync(`which ${bin}`, { stdio: ["ignore", "pipe", "ignore"] }).toString().trim() || null;
  } catch {
    return null;
  }
}

function getProcessTreeRssKB(rootPid) {
  function getChildPids(pid) {
    try {
      return execSync(`pgrep -P ${pid}`, { stdio: ["ignore", "pipe", "ignore"] })
        .toString()
        .split("\n")
        .map((s) => s.trim())
        .filter(Boolean)
        .map(Number);
    } catch {
      return [];
    }
  }
  const pids = [rootPid, ...getChildPids(rootPid)];
  try {
    const out = execSync(`ps -o rss= -p ${pids.join(",")}`, { stdio: ["ignore", "pipe", "ignore"] }).toString();
    return out
      .split("\n")
      .map((s) => parseInt(s.trim(), 10))
      .filter((n) => !Number.isNaN(n))
      .reduce((a, b) => a + b, 0);
  } catch {
    return 0;
  }
}

async function waitForHttp(port, pathName, timeoutMs) {
  const http = await import("node:http");
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const ok = await new Promise((resolve) => {
      const req = http.request({ host: "127.0.0.1", port, path: pathName, method: "GET", timeout: 1000 }, (res) => {
        res.resume();
        res.on("end", () => resolve(res.statusCode === 200));
      });
      req.on("error", () => resolve(false));
      req.on("timeout", () => {
        req.destroy();
        resolve(false);
      });
      req.end();
    });
    if (ok) return;
    await sleep(200);
  }
  throw new Error(`port ${port}${pathName} never became ready within ${timeoutMs}ms`);
}

function spawnTracked(cmd, args, opts = {}) {
  const proc = spawn(cmd, args, opts);
  children.push(proc);
  return proc;
}

async function killTree(proc, signal = "SIGTERM") {
  if (!proc || proc.killed || proc.exitCode !== null) return;
  try {
    proc.kill(signal);
  } catch {}
  await Promise.race([
    new Promise((resolve) => proc.once("exit", resolve)),
    sleep(5000),
  ]);
  if (proc.exitCode === null) {
    try {
      proc.kill("SIGKILL");
    } catch {}
  }
}

// -----------------------------------------------------------------------------
// Config generation
// -----------------------------------------------------------------------------
function nginxConfig(port) {
  const tag = `nginx-${port}`;
  const pidPath = path.join(os.tmpdir(), `ninja-bench-${tag}.pid`);
  const errorLog = path.join(os.tmpdir(), `ninja-bench-${tag}-error.log`);
  const bodyTemp = path.join(os.tmpdir(), `ninja-bench-${tag}-body`);
  const proxyTemp = path.join(os.tmpdir(), `ninja-bench-${tag}-proxy`);
  const confPath = path.join(os.tmpdir(), `ninja-bench-${tag}.conf`);
  const content = `
worker_processes ${WORKER_COUNT};
pid ${pidPath};
error_log ${errorLog} crit;

events {
  worker_connections 8192;
}

http {
  access_log off;
  client_body_temp_path ${bodyTemp};
  proxy_temp_path ${proxyTemp};

  upstream backend {
    server 127.0.0.1:${UPSTREAM_PORT};
    keepalive 128;
  }

  server {
    listen ${port};

    location /small {
      proxy_pass http://backend;
      proxy_http_version 1.1;
      proxy_set_header Connection "";
    }
    location /large {
      proxy_pass http://backend;
      proxy_http_version 1.1;
      proxy_set_header Connection "";
    }
  }
}
`;
  fs.writeFileSync(confPath, content, "utf8");
  return { confPath, pidPath };
}

function ninjaBaselineConfig(port) {
  return `
server:
  host: "0.0.0.0"
  listen: ${port}
  workers: ${WORKER_COUNT}
  compression: false
  rateLimit:
    enabled: false

tls:
  enabled: false

observability:
  logging:
    level: warn
    accessLog: false
  metrics:
    enabled: false
  tracing:
    enabled: false

admin:
  enabled: false

upstreams:
  - id: bench-backend
    url: "http://127.0.0.1:${UPSTREAM_PORT}"
    healthPath: "/health"

routes:
  - path: "/small"
    upstreams: ["bench-backend"]
    cache: { enabled: false }
  - path: "/large"
    upstreams: ["bench-backend"]
    cache: { enabled: false }

loadBalancing:
  strategy: round-robin

rateLimit:
  enabled: false

cache:
  enabled: false
`;
}

function ninjaFullFeatureConfig(port, accessLogPath) {
  return `
server:
  host: "0.0.0.0"
  listen: ${port}
  workers: ${WORKER_COUNT}
  compression: false

tls:
  enabled: false

observability:
  logging:
    level: warn
    accessLog: "${accessLogPath}"
  metrics:
    enabled: true
  tracing:
    enabled: true

admin:
  enabled: false

upstreams:
  - id: bench-backend
    url: "http://127.0.0.1:${UPSTREAM_PORT}"
    healthPath: "/health"

routes:
  - path: "/small"
    upstreams: ["bench-backend"]
    cache: { enabled: true, ttlSeconds: 60 }
  - path: "/large"
    upstreams: ["bench-backend"]
    cache: { enabled: true, ttlSeconds: 60 }

loadBalancing:
  strategy: round-robin

rateLimit:
  enabled: true
  storage: redis
  algorithm: token-bucket
  maxRequests: 10000000
  windowMs: 60000
  redis:
    host: "127.0.0.1"
    port: ${REDIS_PORT}

cache:
  enabled: true
  host: "127.0.0.1"
  port: ${REDIS_PORT}
  ttlSeconds: 60
`;
}

// -----------------------------------------------------------------------------
// wrk driver
// -----------------------------------------------------------------------------
async function runWrk(url, connections, durationSec, rssPids) {
  let peakRssKB = rssPids.reduce((s, p) => s + getProcessTreeRssKB(p), 0);
  const sampler = setInterval(() => {
    const kb = rssPids.reduce((s, p) => s + getProcessTreeRssKB(p), 0);
    if (kb > peakRssKB) peakRssKB = kb;
  }, 200);

  const threads = Math.min(connections, os.cpus().length);
  const output = await new Promise((resolve, reject) => {
    const proc = spawn("wrk", ["-t", String(threads), "-c", String(connections), "-d", `${durationSec}s`, "-s", LUA_REPORT, url]);
    let out = "";
    proc.stdout.on("data", (d) => (out += d.toString()));
    proc.stderr.on("data", (d) => (out += d.toString()));
    proc.on("exit", () => resolve(out));
    proc.on("error", reject);
  });
  clearInterval(sampler);

  const m = output.match(/WRK_RESULT rps=([\d.]+) p50_ms=([\d.]+) p99_ms=([\d.]+) p999_ms=([\d.]+) errors=(\d+) requests=(\d+)/);
  if (!m) {
    throw new Error(`wrk output not parseable for ${url} @ c=${connections}:\n${output}`);
  }
  return {
    rps: Number(m[1]),
    p50Ms: Number(m[2]),
    p99Ms: Number(m[3]),
    p999Ms: Number(m[4]),
    errors: Number(m[5]),
    requests: Number(m[6]),
    peakRssMB: peakRssKB / 1024,
  };
}

async function warmup(url, seconds) {
  await new Promise((resolve) => {
    const proc = spawn("wrk", ["-t", "4", "-c", "100", "-d", `${seconds}s`, url]);
    proc.on("exit", resolve);
    proc.on("error", resolve);
  });
}

// -----------------------------------------------------------------------------
// Target lifecycle
// -----------------------------------------------------------------------------
async function benchTarget(label, { start, port, pids }) {
  log(`Starting target: ${label}`);
  await start();
  await waitForHttp(port, "/small", 20000);
  await sleep(500);

  const rows = [];
  for (const payload of PAYLOADS) {
    const url = `http://127.0.0.1:${port}${payload.path}`;
    log(`  Warming up ${payload.name} for ${WARMUP_SEC}s...`);
    await warmup(url, WARMUP_SEC);
    for (const conns of CONCURRENCIES) {
      log(`  Running ${payload.name} @ ${conns} conns for ${STAGE_SEC}s...`);
      const result = await runWrk(url, conns, STAGE_SEC, pids());
      rows.push({ label, payload: payload.name, connections: conns, ...result });
      log(
        `    rps=${result.rps.toFixed(0)} p50=${result.p50Ms.toFixed(2)}ms p99=${result.p99Ms.toFixed(2)}ms ` +
          `p99.9=${result.p999Ms.toFixed(2)}ms errors=${result.errors} peakRSS=${result.peakRssMB.toFixed(1)}MB`,
      );
      await sleep(1000);
    }
  }
  return rows;
}

// -----------------------------------------------------------------------------
// Machine info
// -----------------------------------------------------------------------------
function machineInfo() {
  let nginxVersion = "unknown";
  try {
    nginxVersion = execSync("nginx -v 2>&1", { shell: "/bin/sh" }).toString().trim();
  } catch (err) {
    nginxVersion = String(err.stdout || err.message).trim();
  }
  let osVersion = `${os.type()} ${os.release()}`;
  try {
    const sw = execSync("sw_vers", { stdio: ["ignore", "pipe", "ignore"] }).toString();
    osVersion = sw.replace(/\n/g, " / ").trim();
  } catch {}
  return {
    cpu: `${os.cpus()[0]?.model || "unknown"} (${os.cpus().length} logical cores)`,
    ram: `${(os.totalmem() / 1024 / 1024 / 1024).toFixed(1)} GB`,
    os: osVersion,
    node: process.version,
    nginx: nginxVersion,
  };
}

// -----------------------------------------------------------------------------
// Report
// -----------------------------------------------------------------------------
function writeReport(allRows, info) {
  const outPath = path.join(REPO_ROOT, "docs", "results", "bench-vs-nginx.md");
  const lines = [];
  lines.push("# ninja-reverse-proxy vs nginx — real-traffic benchmark");
  lines.push("");
  lines.push(`Generated: ${new Date().toISOString()}`);
  lines.push("");
  lines.push("## Machine");
  lines.push("");
  lines.push(`- CPU: ${info.cpu}`);
  lines.push(`- RAM: ${info.ram}`);
  lines.push(`- OS: ${info.os}`);
  lines.push(`- Node: ${info.node}`);
  lines.push(`- nginx: ${info.nginx}`);
  lines.push(`- Workers (both targets): ${WORKER_COUNT}`);
  lines.push(`- Warmup: ${WARMUP_SEC}s, stage duration: ${STAGE_SEC}s per concurrency`);
  lines.push("");
  lines.push("## Results");
  lines.push("");
  lines.push("| Target | Payload | Concurrency | RPS | p50 (ms) | p99 (ms) | p99.9 (ms) | Errors | Peak RSS (MB) |");
  lines.push("| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |");
  for (const r of allRows) {
    lines.push(
      `| ${r.label} | ${r.payload} | ${r.connections} | ${r.rps.toFixed(0)} | ${r.p50Ms.toFixed(2)} | ${r.p99Ms.toFixed(2)} | ${r.p999Ms.toFixed(2)} | ${r.errors} | ${r.peakRssMB.toFixed(1)} |`,
    );
  }
  lines.push("");
  lines.push("Numbers are reported as measured — no tuning applied to only one side beyond matching worker counts.");
  lines.push("");
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, lines.join("\n"), "utf8");
  log(`Report written to ${outPath}`);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
async function cleanupAll() {
  log("Cleaning up all processes...");
  for (const c of children) {
    await killTree(c);
  }
}

async function main() {
  if (!which("wrk")) {
    console.error("wrk not found on PATH. Install with `brew install wrk` and retry, or adapt this script to use `npx autocannon`.");
    process.exit(1);
  }
  if (!which("nginx")) {
    console.error("nginx not found on PATH. Install with `brew install nginx` and retry.");
    process.exit(1);
  }

  const info = machineInfo();
  log(`Machine: ${JSON.stringify(info)}`);

  log("Starting shared upstream (own process)...");
  upstreamProc = spawnTracked(process.execPath, [UPSTREAM_SCRIPT, String(UPSTREAM_PORT)], { stdio: "ignore" });
  await waitForHttp(UPSTREAM_PORT, "/health", 10000);

  log("Starting Redis (own process, for the all-features run)...");
  const redisLog = path.join(os.tmpdir(), "ninja-bench-redis.log");
  redisProc = spawnTracked(
    "redis-server",
    ["--port", String(REDIS_PORT), "--save", "", "--appendonly", "no", "--daemonize", "no", "--logfile", redisLog],
    { stdio: "ignore" },
  );
  await sleep(1000);

  const allRows = [];

  // --- nginx ---
  const nginxCfg = nginxConfig(NGINX_PORT);
  allRows.push(
    ...(await benchTarget("nginx", {
      start: async () => {
        spawnTracked("nginx", ["-c", nginxCfg.confPath, "-g", "daemon off;"], { stdio: "ignore" });
      },
      port: NGINX_PORT,
      pids: () => {
        try {
          return [parseInt(fs.readFileSync(nginxCfg.pidPath, "utf8").trim(), 10)];
        } catch {
          return [];
        }
      },
    })),
  );
  // Stop nginx (last spawned child tracked for it)
  await killTree(children[children.length - 1], "SIGQUIT");

  // --- ninja (baseline) ---
  const ninjaBaselinePath = path.join(os.tmpdir(), "ninja-bench-baseline.yaml");
  fs.writeFileSync(ninjaBaselinePath, ninjaBaselineConfig(NINJA_BASELINE_PORT), "utf8");
  let ninjaBaselineProc;
  allRows.push(
    ...(await benchTarget("ninja", {
      start: async () => {
        ninjaBaselineProc = spawnTracked(process.execPath, [path.join(REPO_ROOT, "dist/index.js"), "--config", ninjaBaselinePath], {
          stdio: "ignore",
          cwd: REPO_ROOT,
        });
      },
      port: NINJA_BASELINE_PORT,
      pids: () => (ninjaBaselineProc ? [ninjaBaselineProc.pid] : []),
    })),
  );
  await killTree(ninjaBaselineProc);

  // --- ninja (all features on) — F1b ---
  const accessLogPath = path.join(os.tmpdir(), "ninja-bench-full-access.log");
  const ninjaFullPath = path.join(os.tmpdir(), "ninja-bench-full.yaml");
  fs.writeFileSync(ninjaFullPath, ninjaFullFeatureConfig(NINJA_FULL_PORT, accessLogPath), "utf8");
  let ninjaFullProc;
  allRows.push(
    ...(await benchTarget("ninja, all features on", {
      start: async () => {
        ninjaFullProc = spawnTracked(process.execPath, [path.join(REPO_ROOT, "dist/index.js"), "--config", ninjaFullPath], {
          stdio: "ignore",
          cwd: REPO_ROOT,
        });
      },
      port: NINJA_FULL_PORT,
      pids: () => (ninjaFullProc ? [ninjaFullProc.pid] : []),
    })),
  );
  await killTree(ninjaFullProc);

  writeReport(allRows, info);

  console.log("\n=== SUMMARY ===");
  for (const r of allRows) {
    console.log(
      `${r.label.padEnd(24)} ${r.payload.padEnd(5)} c=${String(r.connections).padEnd(4)} rps=${r.rps.toFixed(0).padEnd(8)} p50=${r.p50Ms.toFixed(2)}ms p99=${r.p99Ms.toFixed(2)}ms p99.9=${r.p999Ms.toFixed(2)}ms errors=${r.errors}`,
    );
  }
}

process.on("SIGINT", async () => {
  await cleanupAll();
  process.exit(130);
});

try {
  await main();
} catch (err) {
  console.error(`[bench-vs-nginx] FATAL: ${err.stack || err.message}`);
  process.exitCode = 1;
} finally {
  await cleanupAll();
}
